INSERT INTO workplace_info (merge_key, base_info, women_activity_info, compatibility_of_childcare_and_work)
SELECT #{mergeKey},
       bi.base_info_id,
       wa.women_activity_info_id,
       cc.compatibility_of_childcare_and_work_id
FROM (SELECT 1) dummy
         LEFT JOIN base_info bi ON bi.merge_key = #{baseInfoMergeKey}
         LEFT JOIN women_activity_info wa ON wa.merge_key = #{womenActivityMergeKey}
         LEFT JOIN compatibility_of_childcare_and_work cc ON cc.merge_key = #{compatibilityMergeKey}
ON CONFLICT (merge_key) DO NOTHING

UPDATE company
SET workplace_info = #{mergeKey},
    updated_at = now()
WHERE company.corporate_number = #{corporateNumber}
  AND company.workplace_info IS DISTINCT FROM #{mergeKey}
